}

impl ParliamentMember {
    #[must_use]
    /// Creates a new Member of Parliament
    pub const fn new(
        name: String,
        member_id: MemberId,
        party_name: String,
        party_id: u32,
        constituency: String,
    ) -> Self {
        Self {
            name: ParliamentMemberName::new(name),
            member_id,
            party_name: PartyName::new(party_name),
            party_id: PartyId::new(party_id),
            constituency: Constituency::new(constituency),
        }
    }

